	@Test
	public void forceRootGenericPreservesStandardCalendarOrdering() {
		store.setDefaultQueryEvaluationMode(QueryEvaluationMode.STANDARD);
		String query = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
				+ "SELECT ?d WHERE { VALUES ?d { \"2000\"^^xsd:gYear \"2000-02-29Z\"^^xsd:date } } "
				+ "ORDER BY ?d";

		withProperty(NATIVE_FLAG, "true", () -> withProperty(FORCE_FLAG, "true", () -> {
			ValueFactory vf = SimpleValueFactory.getInstance();
			assertThat(values(query, "d"))
					.as("forceRootGeneric must retain the connection's STANDARD comparison semantics")
					.containsExactly(vf.createLiteral("2000", XSD.GYEAR),
							vf.createLiteral("2000-02-29Z", XSD.DATE));
		}));
	}

	private void withProperty(String name, String value, Runnable action) {
		String previous = System.getProperty(name);
		try {
			System.setProperty(name, value);
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, previous);
			}
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(LmdbNativeGenericRootHostTest::render)
					.collect(Collectors.toList());
		}
	}

	private String explain(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private List<Value> values(String query, String bindingName) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(row -> row.getValue(bindingName))
					.toList();
		}
	}

	private static LmdbNativeEvaluationStrategy strategy() {
		return new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null, 0L,
				new EvaluationStatistics(), false);
	}

	private static void configure(LmdbNativeEvaluationStrategy strategy, FederatedServiceResolver resolver,
			QueryOptimizerPipeline pipeline, Supplier<CollectionFactory> collectionFactory) {
		strategy.setFederatedServiceResolver(resolver);
		strategy.setOptimizerPipeline(pipeline);
		strategy.setCollectionFactory(collectionFactory);
		strategy.setTrackTime(true);
		strategy.setTrackResultSize(true);
		strategy.setQueryEvaluationMode(QueryEvaluationMode.STANDARD);
	}

	private static QueryOptimizerPipeline pipeline(AtomicBoolean ran) {
		return () -> List.of((tupleExpr, dataset, bindings) -> ran.set(true));
	}

	private static ConfigurationObservation observe(LmdbNativeEvaluationStrategy view,
			FederatedServiceResolver resolver, Supplier<CollectionFactory> collectionFactory,
			AtomicBoolean pipelineRan) {
		view.optimize(new SingletonSet(), new EvaluationStatistics(), EmptyBindingSet.getInstance());
		return new ConfigurationObservation(view.getFederatedServiceResolver() == resolver,
				view.getCollectionFactory() == collectionFactory, view.isTrackTime(), view.isTrackResultSize(),
				pipelineRan.get(), view.getQueryEvaluationMode());
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining("|"));
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new EmptyIteration<>();
		}

		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}
	}

	private record ConfigurationObservation(boolean resolver, boolean collectionFactory, boolean trackTime,
			boolean trackResultSize, boolean optimizerPipeline, QueryEvaluationMode queryEvaluationMode) {
	}
